def solve(A):
    A=np.array(A); H,W=A.shape
    def dirs(v):
        return {'main':lambda i,j:i-j,'anti':lambda i,j:i+j}
    best=None
    for name,f in dirs().items():
        di=defaultdict(set)
        for i in range(H):
            for j in range(W):
                if A[i,j]: di[f(i,j)].add(A[i,j])
        mono=all(len(v)==1 for v in di.values())
        if best is None or mono: best=(name,di)
    name,di=best
    D=sorted(x for x in di if di[x])
    p=len(D)
    if p==0: return np.zeros_like(A)
    col=residue_map={}
    for s,c in di.items():
        if len(c)!=1: continue
