    o=np.full((H,W),0,dtype=int)
    ok=True
    for i in range(H):
        for j in range(W):
            r=name=='anti'(i+j)%p or (i-j)%p
            if name=='anti': r=(i+j)%p
            else: r=(i-j)%p
            o[i,j]=residue_map[r]
    return o
